import math

def v2(n):
    """Exponent of 2 in the prime factorization of n."""
    if n == 0:
        return float('inf')
    count = 0
    while n > 0 and n % 2 == 0:
        count += 1
        n //= 2
    return count

def f(n):
    """Calculates f(n) = n / 2^(v_2(n))."""
    if n <= 0:
        raise ValueError("n must be positive")
    m = v2(n)
    return n // (2**m)

def check_condition(v, u, max_u=10):
    """Checks if the condition holds for given v and u."""
    if v <= 0 or u <= 0:
        return False

    for k in range(v):
        term1 = f(u + 2 * k)
        term2 = f(u + k)
        difference = term1 - term2

        if difference % 4 != 0:
            # print(f"Failure at k={k}: f({u+2*k}) - f({u+k}) = {difference}. {difference} % 4 = {difference % 4}")
            return False

    return True

def test_candidates(candidates_v, max_u=10):
    results = {}
    print("--- Testing Candidates v ---")

    for v in candidates_v:
        found = False
        for u in range(1, max_u + 1):
            if check_condition(v, u):
                results[v] = f"Satisfied for u = {u}"
                found = True
                break
        if not found:
            results[v] = f"Not satisfied for u up to {max_u}"
        print(f"v={v}: {results[v]}")

    return results

